steps.action_code:
roommate_contacts = []
contacts_page_index = 0
while True:
    contacts_page = apis.phone.search_contacts(
        access_token=phone_access_token,
        relationship="roommate",
        page_index=contacts_page_index,
        page_limit=20,
    )
    roommate_contacts.extend(contacts_page)
    if len(contacts_page) < 20:
        break
    contacts_page_index += 1

print({
    "roommate_contacts": [
        {"first_name": contact["first_name"], "last_name": contact["last_name"], "email": contact["email"]}
        for contact in roommate_contacts
    ]
})

roommate_email_keys = {
    contact["email"].strip().casefold()
    for contact in roommate_contacts
    if contact["email"].strip()
}
roommate_name_keys = {
    (contact["first_name"].strip() + " " + contact["last_name"].strip()).strip().casefold()
    for contact in roommate_contacts
}
today_key = str(current_date_and_time["date"]).strip()

def party_is_roommate(party):
    party_email = party["email"].strip().casefold()
    party_name = party["name"].strip().casefold()
    return (bool(party_email) and party_email in roommate_email_keys) or party_name in roommate_name_keys

target_transactions_by_id = {}
for transaction in social_feed_transactions:
    is_today = str(transaction["created_at"]).strip().startswith(today_key)
    involves_roommate = party_is_roommate(transaction["sender"]) or party_is_roommate(transaction["receiver"])
    if is_today and involves_roommate:
        target_transactions_by_id[transaction["transaction_id"]] = transaction

target_transactions = list(target_transactions_by_id.values())
target_transaction_ids = [transaction["transaction_id"] for transaction in target_transactions]
pre_like_counts = {
    transaction["transaction_id"]: transaction["like_count"]
    for transaction in target_transactions
}
print({
    "transactions_selected_for_liking": [
        {
            "transaction_id": transaction["transaction_id"],
            "created_at": transaction["created_at"],
            "sender": transaction["sender"],
            "receiver": transaction["receiver"],
            "like_count": transaction["like_count"],
        }
        for transaction in target_transactions
    ]
})

verified_social_feed = []
verify_page_index = 0
while True:
    verify_page = apis.venmo.show_social_feed(
        access_token=venmo_access_token,
        page_index=verify_page_index,
        page_limit=20,
    )
    verified_social_feed.extend(verify_page)
    if len(verify_page) < 20:
        break
    verify_page_index += 1

verified_by_id = {transaction["transaction_id"]: transaction for transaction in verified_social_feed}
verified_matching_ids = {
    transaction["transaction_id"]
    for transaction in verified_social_feed
    if str(transaction["created_at"]).strip().startswith(today_key)
    and (party_is_roommate(transaction["sender"]) or party_is_roommate(transaction["receiver"]))
}
if verified_matching_ids != set(target_transaction_ids):
    raise RuntimeError("The post-mutation feed does not contain the same complete target set")
for transaction_id in target_transaction_ids:
    if transaction_id not in verified_by_id:
        raise RuntimeError("A target transaction is missing from the post-mutation feed")
    if verified_by_id[transaction_id]["like_count"] != pre_like_counts[transaction_id] + 1:
        raise RuntimeError("A target transaction's like count did not increase by one")

print({"verified_liked_transaction_count": len(target_transaction_ids)})
